import{_ as a,o,c as t,a2 as i}from"./chunks/framework.gtmkOXzY.js";const g=JSON.parse('{"title":"Updating","description":"","frontmatter":{},"headers":[],"relativePath":"ms-flightsim/updating.md","filePath":"ms-flightsim/updating.md","lastUpdated":null}'),d={name:"ms-flightsim/updating.md"};function n(s,e,r,c,l,u){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="updating" tabindex="-1">Updating <a class="header-anchor" href="#updating" aria-label="Permalink to &quot;Updating&quot;">​</a></h1><p>An update replaces the resource files but keeps your database and your override files. Put your changes in <code>config_overrides.lua</code> and they survive; the exceptions are money and language settings, which live in <code>config.lua</code> (see <a href="./configuration">Configuration</a>).</p><div class="tip custom-block"><p class="custom-block-title">Before you start</p><p>Back up your database and the <code>MS_FlightSim</code> folder. Rolling back is then a copy-paste.</p></div><ol><li>Back up your database and the <code>MS_FlightSim</code> folder.</li><li>Stop the server. Don&#39;t hot-restart a running server mid-update.</li><li>Copy the new files over the old ones. Your <code>config_overrides.lua</code>, <code>hud-config-overrides.js</code> and <code>zz_overrides.lua</code> aren&#39;t in the download, so they stay.</li><li>Re-apply any <code>Config.Payouts</code>, <code>Config.Prices</code> or <code>Config.Language</code> edits to the new <code>config.lua</code>. If you edited other parts of <code>config.lua</code> directly, open <code>config_additions.lua</code> and copy in the new settings listed under each dated entry since your last update.</li><li>Read the release&#39;s <code>CHANGELOG</code> for behaviour changes and settings to decide on.</li><li>Start the server. New database tables and columns are added automatically.</li></ol><p>Database content — licences, hours, ranks, aircraft, companies, layouts drawn in game — always carries over.</p>',5)])])}cons